#!/usr/bin/env bash
# allowed_signers and the context includes current, hooks present (problems). A missing
# signing key is a warning: keys are generated by the ssh preflight, and a fresh machine may not have them yet.
set -euo pipefail
for f in log profile; do
  # shellcheck disable=SC1090
  source "$DOTFILES_DIR/lib/$f.sh"
done
cfg="$HOME/.config/git"
rc=0
for id in "$cfg"/identity.*; do
  [ -f "$id" ] || continue
  key="$(git config --file "$id" user.signingkey || true)"
  key="${key/#\~/$HOME}"
  [ -n "$key" ] || continue
  [ -f "$key" ] || echo "warn: signing key missing for $(basename "$id"): $key (commits there will fail until it exists)"
done
if ! dry="$(DRY_RUN=1 bash "$DOTFILES_DIR/modules/git/install.sh" 2>&1)"; then
  printf '%s\n' "$dry"
  echo "git install dry run failed"
  rc=1
fi
while IFS= read -r f; do
  [ -n "$f" ] || continue
  echo "missing or stale: $f (rerun install)"
  rc=1
done < <(printf '%s\n' "$dry" | sed -n 's/^\[dry\] write //p')
[ -e "$cfg/template/hooks/commit-msg" ] || {
  echo "missing template/hooks/commit-msg"
  rc=1
}
# Repos under the context folders without the commit-msg hook (install fixes them).
while IFS=$'\t' read -r _ root; do
  if [ -z "$root" ] || [ ! -d "$root" ]; then continue; fi
  while IFS= read -r gitdir; do
    [ -e "$gitdir/hooks/commit-msg" ] || echo "repo without commit-msg hook: $(dirname "$gitdir") (dots install)"
  done < <(find "$root" -maxdepth 4 -type d -name .git -not -path '*/node_modules/*' 2>/dev/null)
done < <(cat "$(state_dir)/contexts" 2>/dev/null)
exit $rc
